```json
{
  "root_causes": [
    {
      "service": "frontend",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT 'abn' src, trace_id, span_id, time, duration FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' AND attr_span_kind='Client' UNION ALL SELECT 'norm', trace_id, span_id, time, duration FROM normal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' AND attr_span_kind='Client'), s AS (SELECT trace_id, parent_span_id, time FROM abnormal_traces WHERE service_name='profile' AND attr_span_kind='Server' UNION ALL SELECT trace_id, parent_span_id, time FROM normal_traces WHERE service_name='profile' AND attr_span_kind='Server') SELECT c.src, count(*) n, approx_quantile((epoch(s.time)-epoch(c.time))*1000,0.5) gap_med_ms, approx_quantile((epoch(s.time)-epoch(c.time))*1000,0.95) gap_p95_ms FROM c LEFT JOIN s ON s.parent_span_id=c.span_id GROUP BY c.src",
          "claim": "frontend's GetProfiles client calls wait about 1.9s median before profile's server span starts; normal is about 0ms"
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='profile' AND span_name='profile.Profile/GetProfiles' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "profile's own GetProfiles server spans stay sub-millisecond (p95 under 1ms) during the incident"
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, approx_quantile(duration,0.5)/1e6 med_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name IN ('HTTP /hotels','HTTP /recommendations') GROUP BY 1",
          "claim": "User-facing frontend HTTP /hotels and /recommendations take about 3 seconds at p95, versus roughly 10ms normally"
        },
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT trace_id, span_id, time, span_name FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name IN ('recommendation.Recommendation/GetRecommendations','reservation.Reservation/CheckAvailability','search.Search/Nearby','user.User/CheckUser')), s AS (SELECT trace_id, parent_span_id, time FROM abnormal_traces WHERE attr_span_kind='Server') SELECT c.span_name, count(*) n, approx_quantile((epoch(s.time)-epoch(c.time))*1000,0.5) start_gap_ms_med FROM c JOIN s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id GROUP BY 1",
          "claim": "Other frontend-to-callee calls in the same period start within about 0.2ms, so the delay is specific to the GetProfiles path"
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT trace_id, span_id, time FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles' AND attr_span_kind='Client'), s AS (SELECT trace_id, parent_span_id, time FROM abnormal_traces WHERE service_name='profile' AND attr_span_kind='Server') SELECT count(*) n, approx_quantile((epoch(s.time)-epoch(c.time))*1000,0.5) gap_med_ms FROM c JOIN s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id",
          "claim": "Delayed GetProfiles calls from frontend to profile carry the ~1.9s median delay into frontend's user-facing /hotels and /recommendations responses"
        }
      ]
    }
  ]
}
```

